write: {"content": "import csv

def bubble_sort(items, key=lambda x: x):
    n = len(items)
    for i in range(n):
        swapped = False
        for j in range(0, n - i - 1):
            if key(items[j]) > key(items[j+1]):
                items[j], items[j+1] = items[j+1], items[j]
                swapped = True
        if not swapped:
            break
    return items

def main():
    with open('компоненты.csv', newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f, delimiter=';')
        rows = list(reader)

    sorted_rows = bubble_sort(rows, key=lambda r: r['компонент'].lower())

    print('Сортировка по названию компонента:')
    print('компонент;лицензия;страна правообладателя')
    for r in sorted_rows:
        print(f"{r['компонент']};{r['лицензия']};{r['страна правообладателя']}")

if __name__ == '__main__':
    main()", "path": "bubble_sort.py"}
